import{_ as t}from"./chunks/100.I7A0VXqr.js";import{_ as a,o,c as n,ak as r}from"./chunks/framework.DC-k2h36.js";const l="/projects/esp32Sensor/en/latest/assets/1.COx0oA2Z.webp",i="/projects/esp32Sensor/en/latest/assets/2.C8Q8Ogcp.webp",s="/projects/esp32Sensor/en/latest/assets/3.BE9ddgdY.webp",c="/projects/esp32Sensor/en/latest/assets/4.Cp5TI1cB.webp",y=JSON.parse('{"title":"19. 8-Channel Grayscale Line Follower Sensor","description":"","frontmatter":{},"headers":[],"relativePath":"docs/19. 8-Channel Grayscale Line Follower Sensor.md","filePath":"docs/19. 8-Channel Grayscale Line Follower Sensor.md"}'),h={name:"docs/19. 8-Channel Grayscale Line Follower Sensor.md"};function d(p,e,g,u,m,f){return o(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="_19-8-channel-grayscale-line-follower-sensor" tabindex="-1">19. 8-Channel Grayscale Line Follower Sensor <a class="header-anchor" href="#_19-8-channel-grayscale-line-follower-sensor" aria-label="Permalink to &quot;19. 8-Channel Grayscale Line Follower Sensor&quot;">​</a></h1><h2 id="_19-1-introduction" tabindex="-1">19.1 Introduction <a class="header-anchor" href="#_19-1-introduction" aria-label="Permalink to &quot;19.1 Introduction&quot;">​</a></h2><p>The 8-channel grayscale line follower sensor features a high-performance 32-bit ARM chip and 8 integrated spotlight LEDs. With one-click calibration, it tracks colored lines with precision. Built-in light filtering blocks out sudden ambient light changes and surface glare, keeping line tracking stable through sharp turns and cross intersections.</p><img loading="lazy" height="1070" width="2422" src="'+l+'" class="common_img" style="width:300px;"><h2 id="_19-2-technical-specifications" tabindex="-1">19.2 Technical Specifications <a class="header-anchor" href="#_19-2-technical-specifications" aria-label="Permalink to &quot;19.2 Technical Specifications&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:center;">Parameter</th><th style="text-align:center;">Description</th></tr></thead><tbody><tr><td style="text-align:center;">Operating voltage</td><td style="text-align:center;">5 V</td></tr><tr><td style="text-align:center;">Calibration method</td><td style="text-align:center;">One-click calibration</td></tr><tr><td style="text-align:center;">Effective range</td><td style="text-align:center;">10–40 mm</td></tr><tr><td style="text-align:center;">Connector model</td><td style="text-align:center;">5264-4AW</td></tr><tr><td style="text-align:center;">Mounting compatibility</td><td style="text-align:center;">LEGO-compatible hole spacing</td></tr><tr><td style="text-align:center;">Dimensions</td><td style="text-align:center;">88.4 × 32.0 × 13.7 mm</td></tr></tbody></table><h2 id="_19-3-calibration-method" tabindex="-1">19.3 Calibration Method <a class="header-anchor" href="#_19-3-calibration-method" aria-label="Permalink to &quot;19.3 Calibration Method&quot;">​</a></h2><p>Calibrate the 8-channel grayscale line follower sensor using the following steps:</p><ol><li><p>Place the probes directly over the background area, then long-press the calibration button. The two outer LEDs on each side flash slowly while the four middle LEDs stay lit. Release the button, and the spotlights underneath light up in red, green, and blue in order.</p></li><li><p>When indicator LEDs 1 through 8 all flash together, place the sensor over the target line, then short-press the calibration button once. The four middle LEDs flash slowly while the outer LEDs stay lit, and the spotlights underneath light up in red, green, and blue in order.</p></li><li><p>When all LEDs turn off, calibration of the 8-channel grayscale line follower sensor is complete.</p></li></ol><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>Maintain a probe height between 10–40 mm off the ground during use. When a probe detects the line-following track, its corresponding indicator LED lights up.</strong></p></div><h2 id="_19-4-hands-on-project" tabindex="-1">19.4 Hands-On Project <a class="header-anchor" href="#_19-4-hands-on-project" aria-label="Permalink to &quot;19.4 Hands-On Project&quot;">​</a></h2><h3 id="_19-4-1-project-overview" tabindex="-1">19.4.1 Project Overview <a class="header-anchor" href="#_19-4-1-project-overview" aria-label="Permalink to &quot;19.4.1 Project Overview&quot;">​</a></h3><p>This project uses the 8-channel grayscale line follower sensor to track lines and trigger color alerts on the onboard RGB LEDs. When every probe detects the line, the RGB LEDs turn red. When any probe loses the line, the RGB LEDs turn off, demonstrating how to read sensor data and apply conditional logic in code.</p><h3 id="_19-4-2-hardware-wiring" tabindex="-1">19.4.2 Hardware Wiring <a class="header-anchor" href="#_19-4-2-hardware-wiring" aria-label="Permalink to &quot;19.4.2 Hardware Wiring&quot;">​</a></h3><ul><li>Connect the 8-channel grayscale line follower sensor to port <strong>P1</strong> of the controller using a 4-pin module cable.</li></ul><img loading="lazy" height="588" width="915" src="'+i+'" class="common_img" style="width:400px;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>This sensor supports connection to any port among P1, P2, P3, or P4 on the controller. Ensure that the port configured in the program matches the physical wiring.</strong></p></div><h3 id="_19-4-3-adding-extensions" tabindex="-1">19.4.3 Adding Extensions <a class="header-anchor" href="#_19-4-3-adding-extensions" aria-label="Permalink to &quot;19.4.3 Adding Extensions&quot;">​</a></h3><ul><li>Select <strong>RGB 8 Line follow sensor</strong> under the <strong>Sensor</strong> category.</li></ul><img loading="lazy" height="1040" width="1920" src="'+s+'" class="common_img" style="width:800px;"><h3 id="_19-4-4-complete-program-and-analysis" tabindex="-1">19.4.4 Complete Program and Analysis <a class="header-anchor" href="#_19-4-4-complete-program-and-analysis" aria-label="Permalink to &quot;19.4.4 Complete Program and Analysis&quot;">​</a></h3><ol><li><p>Upon start-up, the hardware port of the 8-channel grayscale line follower sensor is initialized to port P1.</p></li><li><p>Inside the main program loop, the detection status of the 8-channel grayscale line follower sensor is evaluated using conditional statements:</p><ul><li><p>If all probes of the sensor detect the track, set all RGB LEDs to red.</p></li><li><p>If any probe loses the track, turn off all RGB LEDs.</p></li></ul></li><li><p>A 0.1 s delay is executed at the end of each loop iteration before repeating the line detection and lighting routines.</p></li></ol><img loading="lazy" height="503" width="608" src="'+c+'" class="common_img" style="width:500px;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>The source files are available for download under <a href="https://drive.google.com/drive/folders/1TXgifpt9LbPfn2A8MxY_fA1Vpq4xoemE?usp=sharing" target="_blank" rel="noreferrer">Program Files/19 8-Channel Grayscale Line Follower Sensor.sb3</a>.</strong></p></div><h3 id="_19-4-5-program-upload" tabindex="-1">19.4.5 Program Upload <a class="header-anchor" href="#_19-4-5-program-upload" aria-label="Permalink to &quot;19.4.5 Program Upload&quot;">​</a></h3><ul><li>Click <strong>Connect device</strong>, select the serial port, then click the upload button. Wait for the upload success notification to complete the program transfer.</li></ul><img loading="lazy" height="360" width="640" src="'+t+'" class="common_img" style="width:800px;"><h3 id="_19-4-6-program-outcome" tabindex="-1">19.4.6 Program Outcome <a class="header-anchor" href="#_19-4-6-program-outcome" aria-label="Permalink to &quot;19.4.6 Program Outcome&quot;">​</a></h3><p>Once the program upload is complete, align the sensor with the track. When every probe detects the line, the onboard RGB LEDs light up red. Otherwise, the RGB LEDs turn off, providing instant visual feedback on the sensor status.</p>',29)])])}const w=a(h,[["render",d]]);export{y as __pageData,w as default};
